class FrequencyTracker:
    def __init__(self, maxv=10 ** 5, maxf=2 * 10 ** 5):
        self.freq = [0] * (maxv + 1)
        self.cnt = [0] * (maxf + 2)

    def add(self, x):
        f = self.freq[x]
        if f:
            self.cnt[f] -= 1
        self.freq[x] = f + 1
        self.cnt[f + 1] += 1

    def deleteOne(self, x):
        f = self.freq[x]
        if f == 0:
            return
        self.cnt[f] -= 1
        self.freq[x] = f - 1
        if f > 1:
            self.cnt[f - 1] += 1

    def hasFrequency(self, f):
        return f < len(self.cnt) and self.cnt[f] > 0


