##### Python

::: {#8bc5b3f8 .cell execution_count=61}
``` {.python .cell-code}
class HotelScan:
    def __init__(self, rooms=10):
        self.occ = [0] * rooms

    def request(self, ch):
        if ch == "L":
            self.occ[self.occ.index(0)] = 1
        elif ch == "R":
            self.occ[len(self.occ) - 1 - self.occ[::-1].index(0)] = 1
        else:
            self.occ[int(ch)] = 0

    def state(self):
        return "".join(map(str, self.occ))


for s, want in [("LLRL1RL1", "1010000011"), ("L0L0LLRR9", "1100000010")]:
    h = HotelScan()
    for c in s:
        h.request(c)
    assert h.state() == want
```
