class MyHashMap:
    def __init__(self, m=1009):
        self.m = m
        self.buckets = [[] for _ in range(m)]

    def _slot(self, key):
        b = self.buckets[key % self.m]
        for p in b:
            if p[0] == key:
                return b, p
        return b, None

    def put(self, key, val):
        b, p = self._slot(key)
        if p is not None:
            p[1] = val
        else:
            b.append([key, val])

    def get(self, key):
        _, p = self._slot(key)
        return p[1] if p is not None else -1

    def remove(self, key):
        b, p = self._slot(key)
        if p is not None:
            b.remove(p)


m = MyHashMap()
m.put(1, 1); m.put(2, 2)
assert m.get(1) == 1 and m.get(3) == -1
m.put(2, 1)
