``` {.python .cell-code}
class HashMapResize:
    def __init__(self, cap=4, load=0.75):
        self.cap = cap
        self.n = 0
        self.load = load
        self.tbl = [[] for _ in range(cap)]

    def _rehash(self):
        old = self.tbl
        self.cap *= 2
        self.tbl = [[] for _ in range(self.cap)]
        for b in old:
            for kv in b:
                self.tbl[kv[0] % self.cap].append(kv)   # NEW home under the NEW modulus

    def put(self, key, val):
        b = self.tbl[key % self.cap]
        for p in b:
            if p[0] == key:
                p[1] = val
                return
        b.append([key, val])
        self.n += 1
        if self.n > self.load * self.cap:
            self._rehash()

    def get(self, key):
        for p in self.tbl[key % self.cap]:
            if p[0] == key:
                return p[1]
        return -1

    def remove(self, key):
        b = self.tbl[key % self.cap]
        for p in b:
            if p[0] == key:
                b.remove(p)
                self.n -= 1
                return


m = HashMapResize()
m.put(1, 1); m.put(2, 2)
assert m.get(1) == 1 and m.get(3) == -1
m.put(2, 1)
assert m.get(2) == 1
m.remove(2)
assert m.get(2) == -1
# force several resizes and confirm re-homed keys survive
for k in range(1, 20):
    m.put(k, k * 10)
assert m.cap >= 32
for k in range(1, 20):
