class BitsetCount:
    def __init__(self, size):
        self.b = [0] * size
        self.ones = 0

    def fix(self, i):
        if not self.b[i]:
            self.b[i] = 1
            self.ones += 1

    def unfix(self, i):
        if self.b[i]:
            self.b[i] = 0
            self.ones -= 1

    def flip(self):
        self.b = [1 - x for x in self.b]
        self.ones = len(self.b) - self.ones

    def all(self):
        return self.ones == len(self.b)

    def one(self):
        return self.ones > 0

    def count(self):
        return self.ones

    def toString(self):
        return "".join(map(str, self.b))


assert replay_bits(BitsetCount(5), BS_OPS) == BS_OUT
